def rpn_eval(tokens):
    """Evaluate a Reverse Polish Notation expression.

    Parameters
    ----------
    tokens : list
        List containing numbers (int or float) and operators as strings.

    Returns
    -------
    float
        The result of evaluating the RPN expression.
    """
    def op(symbol, a, b):
        # Operands are passed in the order they were popped from the stack
        # (a is the second popped, b is the first popped), so b is the left
        # operand and a is the right operand.
        if symbol == '+':
            return b + a
        if symbol == '-':
            return b - a
        if symbol == '*':
            return b * a
        if symbol == '/':
            return b / a
        raise ValueError(f"Unsupported operator: {symbol}")

    stack = []

    for token in tokens:
        if isinstance(token, (int, float)):
            stack.append(float(token))
        else:
            if len(stack) < 2:
                raise ValueError("Insufficient operands for the operator.")
            a = stack.pop()
            b = stack.pop()
            stack.append(op(token, a, b))

    if len(stack) != 1:
        raise ValueError("The RPN expression did not resolve to a single result.")
    return stack.pop()


print(rpn_eval([3.0, 5.0, '+', 2.0, '/']))
print(rpn_eval([2.0, 2.0, '+']))
print(rpn_eval([7.0, 4.0, '+', 3.0, '-']))
